calls = []
def render(options, active=False):
    calls.append((options, active))
    return options['config']['label'] if active else 'inactive'
cache = MemoLRUCache(2)
first = {'levels': [3, 8], 'config': {'label': 'ready', 'limit': 4}}
second = {'config': {'limit': 4, 'label': 'ready'}, 'levels': [3, 8]}
assert cache.get_or_compute(render, kwargs={'options': first, 'active': True}) == 'ready'
assert cache.get_or_compute(render, kwargs={'active': True, 'options': second}) == 'ready'
assert len(calls) == 1
